    ctx.arc(-10, -10, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#e2e8f0';
    ctx.fillRect(-12, -18, 4, 8);

    ctx.save();
    ctx.translate(0, -20);
    ctx.fillStyle = '#b91c1c';
    ctx.beginPath();
    ctx.arc(0, 0, 15, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.moveTo(4, 8);
    ctx.lineTo(8, -1);
    ctx.lineTo(10, 8);
    ctx.fill();

    ctx.fillStyle = '#334155';
    ctx.beginPath();
