    ctx.fillRect(1, 5, 8, 3);
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(3, 5, 2, 3);
    ctx.fillRect(6, 5, 2, 3);
    ctx.restore();

    ctx.save();
