    ctx.arc(0, 0, 20, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#991b1b';
    ctx.beginPath();
    ctx.moveTo(12, -8);
    ctx.quadraticCurveTo(34, -32, 28, -2);
